      ]);
    }
  }, [mode]);

  const applyRunEvent = useCallback((event: ResearchRunEvent) => {
    if (event.type === "step") {
      setSteps((prev) => {
        const existingIndex = prev.findIndex((step) => step.id === event.step.id);
        if (existingIndex >= 0) {
          return prev.map((step, index) =>
            index === existingIndex
              ? { ...step, ...event.step, tool: { ...step.tool, ...event.step.tool } }
