export type ArtifactFile = {
  path: string;
  size?: number;
  url?: string;
  snippet?: string;
};

export type ExperimentArtifacts = {
  found: boolean;
  projectId?: string;
  root?: string;
  lastModified?: number;
  resultsPath?: string;
  results?: unknown;
  archiveUrl?: string;
  codeFiles: ArtifactFile[];
  figures: ArtifactFile[];
  pdfs: ArtifactFile[];
  message?: string;
};

export type Step = {
  id: string;
  stageIndex: number;
  title: string;
  summary: string;
  duration: string;
  status: StepStatus;
  tool?: ToolBlock;
  output?: { kind: OutputKind };
  sources?: string[];
  artifacts?: ExperimentArtifacts;
};

export const EXAMPLE_TASKS = [
